  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Faithful Love, the Spirit and Justice: Hosea, Joel and Amos$j$, $j${"readings": [{"title": "Hosea 11 (King James Version)", "url": "/portal/bible/Hosea/11"}, {"title": "Joel 2 (King James Version)", "url": "/portal/bible/Joel/2"}, {"title": "Amos 5 (King James Version)", "url": "/portal/bible/Amos/5"}], "body": "Read Hosea 11, Joel 2:12 to 14 and 28 to 32, and Amos 5 in the King James Version. Then read this lesson.\n\nThe twelve minor prophets are shorter books, not less important ones. Hosea, Joel and Amos spoke to God's people about three needs: faithfulness, repentance and justice. Hosea was told to marry a woman who would be unfaithful to him, as a picture of how Israel had been unfaithful to the LORD, yet God's love did not quit. Joel warned of a plague of locusts and called the people to return to the LORD with all their heart, then promised that God would pour out His Spirit on all flesh. Amos was a shepherd and farmer from Judah who confronted the northern kingdom for injustice and empty worship.\n\nKey words: faithful love, repentance, outpouring, justice, righteousness.\n\nYour task: (1) Say what Hosea's marriage taught about God's love. (2) Write Joel 2:28 in your own words. (3) Tell what Amos 5:24 asks of God's people.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 5. The last seventeen books of the Old Testament are the prophets. We have studied the major prophets. Now we study the twelve minor prophets. They are called minor only because their books are shorter. Their messages are strong, and several are quoted in the New Testament.\n\nWe begin with three prophets from the eighth and seventh centuries before Christ: Hosea, Joel and Amos.\n\nHosea spoke to the northern kingdom of Israel. God told him to marry a woman named Gomer, who later left him. Hosea went and bought her back. His own life became a picture of God's love for a people who kept running after other gods. Hosea 11:1 says, When Israel was a child, then I loved him, and called my son out of Egypt. Even when Israel was unfaithful, God did not stop loving them. And Hosea 6:6 says, For I desired mercy, and not sacrifice; and the knowledge of God more than burnt offerings. God wants hearts, not just ceremonies.\n\nJoel prophesied about a great plague of locusts that destroyed the crops. He used it as a call to repentance. In chapter 2 God says, turn ye even to me with all your heart, and with fasting, and with weeping, and with mourning. And rend your heart, and not your garments. Then God gives a wonderful promise. Joel 2:28 says, And it shall come to pass afterward, that I will pour out my spirit upon all flesh; and your sons and your daughters shall prophesy, your old men shall dream dreams, your young men shall see visions. On the Day of Pentecost, Peter stood up in Acts chapter 2 and said, this is that which was spoken by the prophet Joel.\n\nAmos was not a trained prophet. He was a shepherd and a farmer from the village of Tekoa in Judah. God sent him to the northern kingdom, where the rich were getting richer, the poor were being cheated, and the people kept up their religious ceremonies as if nothing was wrong. Amos told them that God was not pleased. He called for justice. Amos 5:24 says, But let judgment run down as waters, and righteousness as a mighty stream. Worship that is not joined to a just life is empty.\n\nYour task is to say what Hosea's marriage taught about God's love, put Joel 2:28 in your own words, and tell what Amos 5:24 asks of God's people. Then take the four question check.\n\nGod asks for faithful hearts and just lives. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Faithful Love, the Spirit and Justice: Hosea, Joel and Amos$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Mercy and the Mighty Message: Obadiah, Jonah and Micah$j$, $j${"readings": [{"title": "Obadiah 1 (King James Version)", "url": "/portal/bible/Obadiah/1"}, {"title": "Jonah 1 (King James Version)", "url": "/portal/bible/Jonah/1"}, {"title": "Jonah 2 (King James Version)", "url": "/portal/bible/Jonah/2"}, {"title": "Jonah 3 (King James Version)", "url": "/portal/bible/Jonah/3"}, {"title": "Jonah 4 (King James Version)", "url": "/portal/bible/Jonah/4"}, {"title": "Micah 5 (King James Version)", "url": "/portal/bible/Micah/5"}, {"title": "Micah 6 (King James Version)", "url": "/portal/bible/Micah/6"}], "body": "Read Obadiah 1 to 4, Jonah 1 to 4 and Micah 5:2 and 6:6 to 8 in the King James Version. Then read this lesson.\n\nObadiah is the shortest book of the Old Testament. It warns Edom, the nation descended from Esau, that pride and cruelty to Judah will bring judgment. Jonah is the story of a prophet who ran from God's call to preach to Nineveh, the capital of the cruel Assyrian empire. God sent a storm and a great fish, Jonah obeyed, the whole city repented, and God showed mercy. Jonah was angry about it, and the book ends with God's question about His compassion. Micah, who lived in the days of Isaiah, called out injustice and said what the LORD requires. He also named the town where a ruler would be born.\n\nKey words: pride, mercy, repentance, justice, Bethlehem.\n\nYour task: (1) Tell why Jonah ran from God. (2) Explain what showed that Nineveh repented and what God did. (3) Write Micah 6:8 in your own words.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we study three prophets with three different messages: Obadiah, Jonah and Micah.\n\nObadiah is the shortest book in the Old Testament, with only one chapter. Its message is to Edom, a nation descended from Esau, Jacob's brother. Edom had stood by when Judah was attacked and even helped the enemy. Obadiah warns that pride is dangerous. Verse 3 says, The pride of thine heart hath deceived thee. A nation that mocks another's suffering will one day face judgment itself.\n\nNext is Jonah, probably the most familiar prophet story in the Bible. God told Jonah to go to Nineveh, the capital of Assyria, and preach against it. The Assyrians were Israel's cruel enemies, and Jonah did not want them to be forgiven. So he got on a ship going the opposite direction. God sent a great storm. The sailors threw Jonah overboard, and the sea became calm. Jonah 1:17 says, Now the LORD had prepared a great fish to swallow up Jonah. And Jonah was in the belly of the fish three days and three nights. From inside the fish Jonah prayed, and God commanded the fish to bring him to dry land.\n\nGod gave Jonah a second chance. He went to Nineveh and preached one short message. The king and the people believed God, fasted and turned from their evil. God saw their works and had mercy. But Jonah was angry. In chapter 4 he explained why he had run in the first place, for I knew that thou art a gracious God, and merciful, slow to anger, and of great kindness. God had compassion for them, and Jonah should have too. The book ends with a question from God about caring for a city full of people.\n\nMicah was a prophet in the days of Isaiah. He spoke against corruption, greedy leaders and false worship. His most famous words are in Micah 6:8. He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God? That is a summary of how to live: be fair, be kind and be humble before God.\n\nMicah also gave a prophecy about a ruler. Micah 5:2 says, But thou, Bethlehem Ephratah, though thou be little among the thousands of Judah, yet out of thee shall he come forth unto me that is to be ruler in Israel; whose goings forth have been from of old, from everlasting. Seven hundred years later, Jesus Christ was born in Bethlehem.\n\nYour task is to tell why Jonah ran from God, explain what showed that Nineveh repented and what God did, and write Micah 6:8 in your own words. Then take the four question check.\n\nGod's mercy is bigger than our prejudices. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Mercy and the Mighty Message: Obadiah, Jonah and Micah$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Trust in Troubled Times: Nahum, Habakkuk and Zephaniah$j$, $j${"readings": [{"title": "Nahum 1 (King James Version)", "url": "/portal/bible/Nahum/1"}, {"title": "Habakkuk 1 (King James Version)", "url": "/portal/bible/Habakkuk/1"}, {"title": "Habakkuk 2 (King James Version)", "url": "/portal/bible/Habakkuk/2"}, {"title": "Habakkuk 3 (King James Version)", "url": "/portal/bible/Habakkuk/3"}, {"title": "Zephaniah 3 (King James Version)", "url": "/portal/bible/Zephaniah/3"}], "body": "Read Nahum 1:1 to 8, Habakkuk 1:1 to 4 and 2:1 to 4, Habakkuk 3:17 to 19 and Zephaniah 3:14 to 17 in the King James Version. Then read this lesson.\n\nNahum, Habakkuk and Zephaniah lived in the last years before Judah fell. Nahum told the city of Nineveh that its violence would end. Years after Jonah, Nineveh had returned to its old cruelty. Habakkuk is a conversation between the prophet and God. He asked why the wicked seemed to win and why God was using Babylon to judge Judah. God answered that the just shall live by his faith. Habakkuk ends with a song of trust in all circumstances. Zephaniah warned of the day of the LORD, then closed with a promise that God would rejoice over His people with singing.\n\nKey words: justice, faith, patience, rejoicing, remnant.\n\nYour task: (1) Say how Nahum differs from Jonah in his message to Nineveh. (2) Write Habakkuk 2:4 in your own words. (3) Tell what Zephaniah 3:17 says God will do.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we study three prophets who lived in the generations before Jerusalem fell: Nahum, Habakkuk and Zephaniah.\n\nNahum wrote to the city of Nineveh. About a hundred and fifty years after Jonah, Nineveh had gone back to violence and cruelty. Nahum said that God, who is slow to anger, will not leave the guilty unpunished. But he also gave a word of comfort to God's people. Nahum 1:7 says, The LORD is good, a strong hold in the day of trouble; and he knoweth them that trust in him. In the middle of a message of judgment, there is a promise that God cares for those who trust in Him.\n\nHabakkuk is different from most prophets. He does not speak to the people on God's behalf. He speaks to God on the people's behalf. He asked hard questions. Why does evil seem to win? Why doesn't God act? When God replied that He would use the Babylonians to discipline Judah, Habakkuk was shocked. How could God use a nation that was even more wicked? Habakkuk then stood on his watch and waited for the answer.\n\nGod's answer is one of the most important lines in the Bible. Habakkuk 2:4 says, but the just shall live by his faith. This verse is quoted three times in the New Testament, in Romans, Galatians and Hebrews. It means that God's people are to keep trusting Him even when they do not understand what He is doing.\n\nHabakkuk closes with a song. He says that even if the fig tree does not blossom, the fields yield no food, the flock is cut off and there is no herd in the stalls, he will not stop trusting. Habakkuk 3:18 says, Yet I will rejoice in the LORD, I will joy in the God of my salvation. That is faith that does not depend on circumstances.\n\nZephaniah warns of the day of the LORD, a time of judgment on the proud and the unfaithful. But the last chapter ends with joy. Zephaniah 3:17 says, The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing. The God of judgment is also a God who delights in His people.\n\nYour task is to say how Nahum differs from Jonah, write Habakkuk 2:4 in your own words, and tell what Zephaniah 3:17 says God will do. Then take the four question check.\n\nKeep trusting God when the answers have not come yet. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Trust in Troubled Times: Nahum, Habakkuk and Zephaniah$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Rebuilding and Looking Ahead: Haggai, Zechariah and Malachi$j$, $j${"readings": [{"title": "Haggai 1 (King James Version)", "url": "/portal/bible/Haggai/1"}, {"title": "Zechariah 4 (King James Version)", "url": "/portal/bible/Zechariah/4"}, {"title": "Zechariah 9 (King James Version)", "url": "/portal/bible/Zechariah/9"}, {"title": "Malachi 3 (King James Version)", "url": "/portal/bible/Malachi/3"}, {"title": "Malachi 4 (King James Version)", "url": "/portal/bible/Malachi/4"}], "body": "Read Haggai 1, Zechariah 4:6, Zechariah 9:9 and Malachi 3 and 4 in the King James Version. Then read this lesson.\n\nThe last three minor prophets spoke to the people who returned from Babylon. Haggai and Zechariah encouraged the people to finish rebuilding the temple, which had stopped for about sixteen years. Haggai told them to consider their ways and put God first. Zechariah gave visions and promises, including a King who would come riding on a donkey. Malachi, the last book of the Old Testament, spoke about a generation that had grown lazy in worship and in giving. Malachi calls the people to bring their tithes and promises that a messenger will prepare the way for the LORD. The Old Testament ends with hope that the Sun of righteousness will arise.\n\nKey words: rebuild, priorities, Spirit, King, messenger.\n\nYour task: (1) Tell what Haggai told the people to do. (2) Name how Zechariah said the King would come. (3) Say what Malachi told the people about tithes.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "We have reached the end of the Old Testament, and the last three prophets speak to people who had come home from Babylon.\n\nWhen Cyrus let the Jews return, they began to rebuild the temple. But opposition came, and they stopped. For about sixteen years the house of God sat unfinished while the people worked on their own houses. Then God sent Haggai. Haggai 1:5 says, Now therefore thus saith the LORD of hosts; Consider your ways. He asked the people to think about their priorities. They had put themselves first and God second. The people listened, and the work began again.\n\nZechariah was a young prophet who worked alongside Haggai. He saw a series of visions to encourage the builders. In one of them God told Zerubbabel, the governor, that the work would be done not by human strength. Zechariah 4:6 says, Not by might, nor by power, but by my spirit, saith the LORD of hosts. We cannot do God's work in our own strength.\n\nZechariah also looked far ahead to the coming Messiah. Zechariah 9:9 says, Rejoice greatly, O daughter of Zion; shout, O daughter of Jerusalem: behold, thy King cometh unto thee: he is just, and having salvation; lowly, and riding upon an ass, and upon a colt the foal of an ass. Five hundred years later, Jesus rode into Jerusalem on a donkey, and the crowds cried out Hosanna.\n\nMalachi is the last book of the Old Testament. By his time, the temple had been rebuilt, but the people had become cold toward God. They brought poor offerings, held back their tithes, and complained that serving God did not pay. Malachi told them plainly. Malachi 3:10 says, Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it. Giving to God is an act of trust.\n\nMalachi also promised that God would send a messenger to prepare the way. In the New Testament that messenger is John the Baptist. And the book closes with a promise in Malachi 4:2, But unto you that fear my name shall the Sun of righteousness arise with healing in his wings. After Malachi, the voice of the prophets was quiet for about four hundred years. But the promise of the Messiah was still waiting.\n\nYour task is to tell what Haggai told the people, name how Zechariah said the King would come, and say what Malachi told the people about tithes. Then take the four question check and the Unit 5 quiz.\n\nPut God first, and trust Him to supply. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Rebuilding and Looking Ahead: Haggai, Zechariah and Malachi$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Message for Today$j$, $j${"prompt": "Choose one message from the minor prophets, such as Micah 6:8, Habakkuk 2:4, Zechariah 4:6 or Malachi 3:10. Write one paragraph of 150 to 200 words. Explain who the prophet was, what the verse means in its setting, and how a student can live out that message this week. Quote the verse from the King James Version.", "rubric": "Total 100. Accurate setting and meaning of the verse: 30. Describes the prophet and his time: 20. Gives a clear way to apply the message, with the verse quoted from the King James Version: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Message for Today$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Mercy for Our Enemies$j$, $j${"prompt": "Jonah did not want God to show mercy to people he saw as enemies. Think about a time it was hard to forgive someone or to be kind to someone. Describe what happened and explain what Jonah teaches us about God's mercy. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Mercy for Our Enemies$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Faithful Love, the Spirit and Justice: Hosea, Joel and Amos$j$, $j${"questions": [{"q": "What did Hosea's marriage picture?", "options": ["The rebuilding of the temple", "The fall of Babylon", "God's judgment on Egypt", "God's faithful love for an unfaithful people"]}, {"q": "What did Joel promise God would pour out upon all flesh?", "options": ["Silver and gold", "His spirit", "A flood", "Fire from heaven"]}, {"q": "What was Amos' work before God sent him as a prophet?", "options": ["A shepherd and farmer", "A king", "A priest", "A soldier"]}, {"q": "What does Amos 5:24 ask for?", "options": ["More feasts", "Larger sacrifices", "A new king", "Justice and righteousness flowing like a stream"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Faithful Love, the Spirit and Justice: Hosea, Joel and Amos$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,3}'::int[], array[$j$Hosea's life showed God's steady love for unfaithful Israel.$j$,$j$Joel 2:28 says God will pour out His spirit upon all flesh.$j$,$j$Amos was a herdsman and gatherer of sycomore fruit from Tekoa.$j$,$j$Amos called for judgment to run down as waters and righteousness as a mighty stream.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Faithful Love, the Spirit and Justice: Hosea, Joel and Amos$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Mercy and the Mighty Message: Obadiah, Jonah and Micah$j$, $j${"questions": [{"q": "To which nation was the message of Obadiah directed?", "options": ["Babylon", "Egypt", "Edom", "Assyria"]}, {"q": "Why did Jonah run from God's command?", "options": ["He wanted to be a king", "He did not know where Nineveh was", "He did not want Nineveh to be shown mercy", "He was afraid of the sea"]}, {"q": "What happened when Nineveh heard God's message?", "options": ["Jonah became king", "The city refused to listen", "The people repented and God had mercy", "The city was destroyed at once"]}, {"q": "What does Micah 6:8 say the LORD requires?", "options": ["To do justly, love mercy and walk humbly with God", "To bring many sacrifices", "To fight his enemies", "To build a temple"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Mercy and the Mighty Message: Obadiah, Jonah and Micah$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,0}'::int[], array[$j$Obadiah warned Edom, the descendants of Esau.$j$,$j$Jonah did not want his enemies to be forgiven.$j$,$j$The king and the people turned from evil and God spared the city.$j$,$j$Micah summarizes what is good: justice, mercy and humility.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Mercy and the Mighty Message: Obadiah, Jonah and Micah$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Trust in Troubled Times: Nahum, Habakkuk and Zephaniah$j$, $j${"questions": [{"q": "To which city was Nahum's message addressed?", "options": ["Jerusalem", "Nineveh", "Babylon", "Samaria"]}, {"q": "What did God answer Habakkuk in Habakkuk 2:4?", "options": ["The just shall live by his faith", "Flee to Egypt", "Stop praying", "Build an army"]}, {"q": "What does Habakkuk 3:18 show Habakkuk deciding?", "options": ["To stop prophesying", "To leave Judah", "To become king", "To rejoice in the LORD no matter what"]}, {"q": "What does Zephaniah 3:17 say the LORD will do over His people?", "options": ["Forget them", "Test them by fire", "Hide from them", "Joy over them with singing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Trust in Troubled Times: Nahum, Habakkuk and Zephaniah$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,3,3}'::int[], array[$j$Nahum prophesied the fall of Nineveh.$j$,$j$God said that the just shall live by his faith.$j$,$j$Habakkuk said he would rejoice in the LORD and joy in the God of his salvation.$j$,$j$The LORD will rejoice over His people with singing.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Trust in Troubled Times: Nahum, Habakkuk and Zephaniah$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Rebuilding and Looking Ahead: Haggai, Zechariah and Malachi$j$, $j${"questions": [{"q": "What did Haggai tell the people to do in Haggai 1:5?", "options": ["Make a treaty", "Consider their ways", "Build a wall", "Return to Egypt"]}, {"q": "According to Zechariah 4:6, how would God's work be done?", "options": ["By wealth", "By might and power", "By armies", "By my spirit, saith the LORD of hosts"]}, {"q": "How did Zechariah 9:9 say the King would come to Jerusalem?", "options": ["In a chariot of gold", "By ship", "Lowly, riding on an ass", "With an army"]}, {"q": "What did Malachi tell the people to bring into the storehouse?", "options": ["Weapons", "Letters", "Idols", "Tithes"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Rebuilding and Looking Ahead: Haggai, Zechariah and Malachi$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,3}'::int[], array[$j$Haggai called the people to think about their priorities and rebuild the temple.$j$,$j$Zechariah said, Not by might, nor by power, but by my spirit.$j$,$j$Zechariah pictured a just and lowly King riding upon an ass.$j$,$j$Malachi 3:10 calls the people to bring all the tithes into the storehouse.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Rebuilding and Looking Ahead: Haggai, Zechariah and Malachi$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: The Minor Prophets, Hosea to Malachi$j$, $j${"questions": [{"q": "Which prophet's marriage was a picture of God's love for unfaithful Israel?", "options": ["Joel", "Micah", "Hosea", "Amos"]}, {"q": "Which prophet ran from God's call to preach to Nineveh?", "options": ["Haggai", "Nahum", "Obadiah", "Jonah"]}, {"q": "Which prophet named Bethlehem as the place a ruler would come from?", "options": ["Joel", "Micah", "Amos", "Zechariah"]}, {"q": "What does Habakkuk 2:4 say the just shall do?", "options": ["Build an altar", "Wait for kings", "Flee from trouble", "Live by his faith"]}, {"q": "Which prophet urged the people to rebuild the temple and consider their ways?", "options": ["Nahum", "Joel", "Obadiah", "Haggai"]}, {"q": "Which is the last book of the Old Testament?", "options": ["Haggai", "Zechariah", "Malachi", "Nahum"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Minor Prophets, Hosea to Malachi$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,3,3,2}'::int[], array[$j$Hosea's life illustrated God's faithful love.$j$,$j$Jonah ran toward Tarshish instead of going to Nineveh.$j$,$j$Micah 5:2 names Bethlehem Ephratah.$j$,$j$The just shall live by his faith.$j$,$j$Haggai encouraged the returned exiles to put God first.$j$,$j$Malachi closes the Old Testament.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Minor Prophets, Hosea to Malachi$j$ on conflict (item_id) do nothing;
